import { MakeLogicType, afterMount, connect, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { projectLogic } from 'scenes/projectLogic'

import { tasksModelsRetrieve } from 'products/tasks/frontend/generated/api'
import type { ModelChoiceApi } from 'products/tasks/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taskModelPickerLogicValues {
    currentProjectId: number | null // projectLogic
    models: ModelChoiceApi[]
    modelsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taskModelPickerLogicActions {
    loadModels: () => any
    loadModelsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadModelsSuccess: (
        models: ModelChoiceApi[],
        payload?: any
    ) => {
        models: ModelChoiceApi[]
        payload?: any
    }
}

export type taskModelPickerLogicType = MakeLogicType<taskModelPickerLogicValues, taskModelPickerLogicActions>

export const taskModelPickerLogic = kea<taskModelPickerLogicType>([
    path(['products', 'tasks', 'frontend', 'components', 'TaskModelPicker', 'taskModelPickerLogic']),
    connect(() => ({
        values: [projectLogic, ['currentProjectId']],
    })),
    loaders(({ values }) => ({
        models: [
            [] as ModelChoiceApi[],
            {
                loadModels: async (): Promise<ModelChoiceApi[]> => {
                    const response = await tasksModelsRetrieve(String(values.currentProjectId))
                    return response.models
                },
            },
        ],
    })),
    afterMount(({ actions }) => {
        actions.loadModels()
    }),
])
